(()=>{'use strict';let last='';function track(){if(document.visibilityState==='hidden'||navigator.webdriver)return;const path=location.pathname;if(path===last)return;last=path;try{let visitor=localStorage.getItem('gmach-visitor-id');if(!visitor){visitor=crypto.randomUUID();localStorage.setItem('gmach-visitor-id',visitor)}let visit;try{visit=JSON.parse(localStorage.getItem('gmach-visit-session')||'null')}catch{}if(!visit||Date.now()-visit.at>1800000)visit={id:crypto.randomUUID()};visit.at=Date.now();localStorage.setItem('gmach-visit-session',JSON.stringify(visit));fetch('/api/analytics/visit',{method:'POST',credentials:'same-origin',keepalive:true,headers:{'Content-Type':'application/json'},body:JSON.stringify({visitorId:visitor,sessionId:visit.id,path,referrer:document.referrer&&new URL(document.referrer).host!==location.host?document.referrer:''})}).catch(()=>{})}catch{}}
for(const key of ['pushState','replaceState']){const original=history[key];history[key]=function(...args){const result=original.apply(this,args);track();return result}}
window.addEventListener('popstate',track);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){last='';track()}});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',track,{once:true});else track();})();
